import React, { useState } from 'react';
import { Grommet, Box, Form, FormField, TextInput, CheckBox, Button } from 'grommet';

const theme = {
  global: {
    colors: {
      brand: '#7D4CDB',
    },
  },
};

export const App = () => {
  // value.haveAlias controls whether alias field is shown
  const [formValue, setFormValue] = useState({ name: '', haveAlias: false, alias: '' });
  const [isValid, setIsValid] = useState(false);

  return (
    <Grommet theme={theme} full>
      <Box pad="large" width="medium">
        <Form
          value={formValue}
          onChange={({ value }) => setFormValue(value)}
          onValidate={({ valid }) => setIsValid(valid)}
        >
          {/* Required Name field */}
          <FormField name="name" label="Name" required>
            <TextInput name="name" />
          </FormField>

          {/* CheckBox to toggle alias */}
          <FormField name="haveAlias" component={CheckBox} label="have alias?" />

          {/* Conditionally render required Alias field */}
          {formValue.haveAlias && (
            <FormField name="alias" label="Alias" required>
              <TextInput name="alias" />
            </FormField>
          )}

          <Box direction="row" gap="small" margin={{ top: 'medium' }}>
            <Button
              type="reset"
              label="Reset"
              onClick={() => setFormValue({ name: '', haveAlias: false, alias: '' })}
            />
            <Button type="submit" label="Update" primary disabled={!isValid} />
          </Box>
        </Form>
      </Box>
    </Grommet>
  );
};
